INSERT INTO public.events VALUES (96, 'Hội Nghị Nhà Phát Triển Game & Ứng Dụng Đồ Họa 3D Thời Gian Thực', 'Sự kiện thường niên lớn nhất dành cho game developers, 3D artists với các chủ đề đồ họa Unreal Engine 5, ray-tracing phần cứng, sinh tài nguyên 3D bằng Generative AI.', 42, 'Nhà Thi Đấu Thể Thao Phú Thọ, TP. Hồ Chí Minh', '2026-09-26 09:00:00+00', '2026-09-27 18:00:00+00', 'PUBLISHED', '2026-09-25 02:21:53.331017+00', '2026-09-25 02:40:50.903784+00', '26/09/2026 09:00', '27/09/2026 18:00', '219 Lý Thường Kiệt, Phường 15, Quận 11, TP. Hồ Chí Minh', 'https://maps.google.com/maps?q=Nha+Thi+Dau+Phu+Tho+TPHCM&t=&z=16&ie=UTF8&iwloc=&output=embed', 800, 630, 'hoi-nghi-game-developers-do-hoa-3d-2026', 'Game & 3D', 'https://images.unsplash.com/photo-1511512578047-dfb367046420?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 12, NULL, NULL);
INSERT INTO public.events VALUES (106, 'AI Hackathon & Demo Day: Future Innovators 2026', '48 giờ lập trình liên tục thử thách các tài năng trẻ sáng tạo các ứng dụng AI tạo sinh, Agentic workflows giải quyết các bài toán cấp bách với tổng giải thưởng 1 tỷ VNĐ.', 53, 'Đại Học FPT TP. Hồ Chí Minh', '2026-11-21 08:00:00+00', '2026-11-22 21:00:00+00', 'PUBLISHED', '2026-09-25 02:21:55.680724+00', '2026-09-25 02:40:53.978892+00', '21/11/2026 08:00', '22/11/2026 21:00', 'Lô E2a-7, Đường D1, Khu Công nghệ cao, Long Thạnh Mỹ, TP. Thủ Đức, TP. Hồ Chí Minh', 'https://maps.google.com/maps?q=FPT+University+HCMC&t=&z=16&ie=UTF8&iwloc=&output=embed', 500, 460, 'ai-hackathon-demo-day-future-innovators-2026', 'Hackathon & Đổi Mới', 'https://images.unsplash.com/photo-1504384308090-c894fdcc538d?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 20, NULL, NULL);
INSERT INTO public.events VALUES (109, 'Fintech Vietnam Open Banking & Payment Summit 2026', 'Diễn đàn tài chính công nghệ phân tích xu hướng ngân hàng mở (Open Banking), thanh toán số xuyên biên giới theo chuẩn QR quốc tế, sinh trắc học và AI phòng chống gian lận tài chính.', 41, 'Khách sạn Lotte Hotel Hanoi', '2026-10-20 08:30:00+00', '2026-10-21 17:00:00+00', 'PUBLISHED', '2026-09-25 02:40:48.130219+00', '2026-09-25 02:40:48.130219+00', '20/10/2026 08:30', '21/10/2026 17:00', '54 Liễu Giai, Phường Cống Vị, Quận Ba Đình, Hà Nội', 'https://maps.google.com/maps?q=Lotte+Hotel+Hanoi&t=&z=16&ie=UTF8&iwloc=&output=embed', 700, 540, 'fintech-vietnam-open-banking-payment-summit-2026', 'Công Nghệ Tài Chính', 'https://images.unsplash.com/photo-1559526324-4b87b5e36e44?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, true, 2, NULL, NULL);
INSERT INTO public.events VALUES (101, 'Green Tech & Năng Lượng Tái Tạo Summit Vietnam 2026', 'Chiến lược chuyển đổi năng lượng xanh hướng tới Net Zero 2050, lưu trữ pin thông minh quy mô lưới điện, tín chỉ carbon và các công nghệ giảm phát thải công nghiệp tiên tiến.', 48, 'Trung Tâm Hội Nghị White Palace Hoàng Văn Thụ, TP.HCM', '2026-11-05 09:00:00+00', '2026-11-06 17:00:00+00', 'PUBLISHED', '2026-09-25 02:21:54.442351+00', '2026-09-25 02:40:48.635828+00', '05/11/2026 09:00', '06/11/2026 17:00', '194 Hoàng Văn Thụ, Phường 9, Quận Phú Nhuận, TP. Hồ Chí Minh', 'https://maps.google.com/maps?q=White+Palace+Hoang+Van+Thu&t=&z=16&ie=UTF8&iwloc=&output=embed', 800, 610, 'green-tech-nang-luong-tai-tao-summit-2026', 'Chuyển Đổi Xanh', 'https://images.unsplash.com/photo-1497435334941-8c899ee9e8e9?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, true, 4, NULL, NULL);
INSERT INTO public.events VALUES (89, 'TechFest Global Innovation & Startup Summit 2026', 'Ngày hội đổi mới sáng tạo quốc tế kết nối hơn 300 quỹ đầu tư mạo hiểm (VCs), 500 startup công nghệ đột phá và các lãnh đạo công nghệ nhằm thúc đẩy hệ sinh thái khởi nghiệp kỳ lân.', 39, 'Trung Tâm Hội Chợ & Triển Lãm Sài Gòn (SECC), TP. Hồ Chí Minh', '2026-10-25 08:00:00+00', '2026-10-27 18:00:00+00', 'PUBLISHED', '2026-09-25 02:21:51.705234+00', '2026-09-25 02:40:49.262055+00', '25/10/2026 08:00', '27/10/2026 18:00', '799 Nguyễn Văn Linh, Tân Phú, Quận 7, TP. Hồ Chí Minh', 'https://maps.google.com/maps?q=SECC+Quan+7+Ho+Chi+Minh&t=&z=16&ie=UTF8&iwloc=&output=embed', 1000, 890, 'techfest-global-innovation-2026', 'Khởi Nghiệp', 'https://images.unsplash.com/photo-1475721027785-f74eccf877e2?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 7, NULL, NULL);
INSERT INTO public.events VALUES (90, 'Cybersecurity & Data Privacy Forum 2026', 'Diễn đàn an ninh thông tin cấp cao về phòng chống mã độc tống tiền (Ransomware), bảo mật kiến trúc Zero Trust, an ninh dữ liệu đám mây và tuân thủ nghị định bảo vệ dữ liệu cá nhân (PDPD).', 40, 'Khách sạn JW Marriott Hanoi', '2026-09-28 08:30:00+00', '2026-09-29 17:00:00+00', 'PUBLISHED', '2026-09-25 02:21:51.963462+00', '2026-09-25 02:40:48.40131+00', '28/09/2026 08:30', '29/09/2026 17:00', 'Số 8 Đỗ Đức Dục, Mễ Trì, Nam Từ Liêm, Hà Nội', 'https://maps.google.com/maps?q=JW+Marriott+Hotel+Hanoi&t=&z=16&ie=UTF8&iwloc=&output=embed', 600, 520, 'cybersecurity-data-privacy-forum-2026', 'An Ninh Mạng', 'https://images.unsplash.com/photo-1550751827-4bd374c3f58b?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, true, 3, NULL, NULL);
INSERT INTO public.events VALUES (92, 'Web3 & Blockchain Developers Conclave 2026', 'Nơi quy tụ các lập trình viên hàng đầu hệ sinh thái Web3, phân tích chuyên sâu về Layer 2 rollups, Smart Contract Security, Zero-Knowledge Proofs và tài chính phi tập trung (DeFi 3.0).', 38, 'Keangnam Hanoi Landmark Tower', '2026-09-15 08:30:00+00', '2026-09-16 17:30:00+00', 'COMPLETED', '2026-09-25 02:21:52.415151+00', '2026-09-25 02:40:49.476363+00', '15/09/2026 08:30', '16/09/2026 17:30', 'Tòa nhà Keangnam Landmark 72, Mễ Trì, Cầu Giấy, Hà Nội', 'https://maps.google.com/maps?q=Keangnam+Hanoi+Landmark+Tower&t=&z=16&ie=UTF8&iwloc=&output=embed', 500, 480, 'web3-blockchain-developers-conclave-2026', 'Blockchain & Web3', 'https://images.unsplash.com/photo-1639762681485-074b7f938ba0?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 8, NULL, NULL);
INSERT INTO public.events VALUES (91, 'Hội Thảo Quốc Tế: Đạo Đức Trong Kỷ Nguyên Trí Tuệ Nhân Tạo', 'Diễn đàn học thuật chuyên sâu về các nguyên tắc đạo đức AI, tính minh bạch của mô hình ngôn ngữ lớn (LLMs), giải quyết thiên vị dữ liệu và khuôn khổ pháp lý quốc tế cho Trí tuệ nhân tạo.', 36, 'Trường Đại học VinUniversity, Hà Nội', '2026-09-12 09:00:00+00', '2026-09-13 17:00:00+00', 'COMPLETED', '2026-09-25 02:21:52.198267+00', '2026-09-25 02:40:49.86921+00', '12/09/2026 09:00', '13/09/2026 17:00', 'Khu đô thị Vinhomes Ocean Park, Đa Tốn, Gia Lâm, Hà Nội', 'https://maps.google.com/maps?q=VinUniversity+Hanoi&t=&z=16&ie=UTF8&iwloc=&output=embed', 400, 385, 'dao-duc-trong-ky-nguyen-ai', 'Đạo Đức AI', 'https://images.unsplash.com/photo-1531482615713-2afd69097998?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 9, NULL, NULL);
INSERT INTO public.events VALUES (95, 'Workshop Chuyên Sâu: Xây Dựng AI Agents Với LangGraph & pgvector', 'Lớp đào tạo thực hành chuyên sâu hướng dẫn kỹ sư lập trình Multi-Agent Workflows, RAG kết hợp Vector Database pgvector trên PostgreSQL và triển khai mô hình Human-in-the-Loop.', 36, 'Dreamplex Coworking Space, TP. Hồ Chí Minh', '2026-09-25 08:30:00+00', '2026-09-25 17:30:00+00', 'ONGOING', '2026-09-25 02:21:53.087081+00', '2026-09-25 02:40:50.204009+00', '25/09/2026 08:30', '25/09/2026 17:30', '195 Điện Biên Phủ, Phường 15, Bình Thạnh, TP. Hồ Chí Minh', 'https://maps.google.com/maps?q=Dreamplex+195+Dien+Bien+Phu&t=&z=16&ie=UTF8&iwloc=&output=embed', 300, 295, 'workshop-ai-agents-langgraph-pgvector', 'Workshop AI', 'https://images.unsplash.com/photo-1522071820081-009f0129c71c?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 10, NULL, NULL);
INSERT INTO public.events VALUES (94, 'Diễn Đàn Chuyển Đổi Số Doanh Nghiệp & Smart Manufacturing', 'Giới thiệu giải pháp nhà máy thông minh Smart Factory 4.0, tự động hóa chuỗi cung ứng với IoT công nghiệp và phân tích dữ liệu sản xuất dự đoán bảo trì chính xác bằng AI.', 43, 'Khách sạn Sheraton Saigon Hotel & Towers', '2026-09-22 09:00:00+00', '2026-09-23 16:30:00+00', 'COMPLETED', '2026-09-25 02:21:52.862485+00', '2026-09-25 02:40:50.578478+00', '22/09/2026 09:00', '23/09/2026 16:30', '88 Đồng Khởi, Phường Bến Nghé, Quận 1, TP. Hồ Chí Minh', 'https://maps.google.com/maps?q=Sheraton+Saigon+Hotel&t=&z=16&ie=UTF8&iwloc=&output=embed', 450, 420, 'chuyen-doi-so-doanh-nghiep-smart-manufacturing', 'Chuyển Đổi Số', 'https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 11, NULL, NULL);
INSERT INTO public.events VALUES (97, 'Triển Lãm Robot & Tự Động Hóa Công Nghiệp Thông Minh 2026', 'Trưng bày hơn 200 dòng robot tự hành (AGV/AMR), cánh tay robot công nghiệp thế hệ mới, thị giác máy tính Computer Vision cho dây chuyền đóng gói và thiết bị không người lái.', 44, 'Trung Tâm Triển Lãm Quốc Tế WTC Expo Bình Dương', '2026-10-02 09:00:00+00', '2026-10-04 17:00:00+00', 'PUBLISHED', '2026-09-25 02:21:53.530287+00', '2026-09-25 02:40:51.321368+00', '02/10/2026 09:00', '04/10/2026 17:00', 'Số A19 đường Hùng Vương, Phường Hòa Phú, TP. Thủ Dầu Một, Bình Dương', 'https://maps.google.com/maps?q=WTC+Expo+Binh+Duong&t=&z=16&ie=UTF8&iwloc=&output=embed', 950, 710, 'trien-lam-robot-tu-dong-hoa-2026', 'Robot & Tự Động Hóa', 'https://images.unsplash.com/photo-1485827404703-89b55fcc595e?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 13, NULL, NULL);
INSERT INTO public.events VALUES (98, 'Hội Thảo Quốc Tế Semiconductor & Chip Thiết Kế Vi Mạch', 'Tọa đàm hợp tác chiến lược giữa các tập đoàn bán dẫn hàng đầu toàn cầu, viện nghiên cứu và trường đại học nhằm đào tạo nhân lực thiết kế chip vi mạch bán dẫn.', 45, 'Khu Công Nghệ Cao TP. Hồ Chí Minh (SHTP)', '2026-10-06 08:30:00+00', '2026-10-07 17:00:00+00', 'PUBLISHED', '2026-09-25 02:21:53.76226+00', '2026-09-25 02:40:51.786756+00', '06/10/2026 08:30', '07/10/2026 17:00', 'Đường D1, Phường Tân Phú, TP. Thủ Đức, TP. Hồ Chí Minh', 'https://maps.google.com/maps?q=Saigon+Hi-Tech+Park+TP+Thu+Duc&t=&z=16&ie=UTF8&iwloc=&output=embed', 500, 410, 'semiconductor-chip-thiet-ke-vi-mach', 'Bán Dẫn & Vi Mạch', 'https://images.unsplash.com/photo-1518770660439-4636190af475?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 14, NULL, NULL);
INSERT INTO public.events VALUES (99, 'Data Engineering & Big Data Analytics Forum 2026', 'Khám phá kiến trúc Data Lakehouse hiện đại, xử lý luồng dữ liệu thời gian thực quy mô Terabyte với Apache Kafka/Flink và tối ưu hóa chi phí lưu trữ đám mây.', 46, 'Tòa Nhà FPT Tower Cầu Giấy, Hà Nội', '2026-10-14 09:00:00+00', '2026-10-15 17:30:00+00', 'PUBLISHED', '2026-09-25 02:21:53.985895+00', '2026-09-25 02:40:52.289148+00', '14/10/2026 09:00', '15/10/2026 17:30', 'Số 10 Phạm Văn Bạch, Dịch Vọng, Cầu Giấy, Hà Nội', 'https://maps.google.com/maps?q=FPT+Tower+Pham+Van+Bach+Hanoi&t=&z=16&ie=UTF8&iwloc=&output=embed', 600, 430, 'data-engineering-big-data-analytics-2026', 'Dữ Liệu & Big Data', 'https://images.unsplash.com/photo-1558494949-ef010cbdcc31?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 15, NULL, NULL);
INSERT INTO public.events VALUES (100, 'Hội Nghị Y Tế Thông Minh & MedTech Innovation 2026', 'Ứng dụng AI phân tích hình ảnh y tế, chẩn đoán bệnh lý chính xác, hồ sơ bệnh án điện tử tập trung (EMR) và công nghệ giải trình tự gen hỗ trợ y học cá thể hóa.', 47, 'Khách sạn InterContinental Hanoi Landmark72', '2026-10-22 08:30:00+00', '2026-10-23 17:00:00+00', 'PUBLISHED', '2026-09-25 02:21:54.212257+00', '2026-09-25 02:40:52.668087+00', '22/10/2026 08:30', '23/10/2026 17:00', 'Tòa nhà Keangnam Hanoi Landmark, E6 Phạm Hùng, Cầu Giấy, Hà Nội', 'https://maps.google.com/maps?q=InterContinental+Hanoi+Landmark72&t=&z=16&ie=UTF8&iwloc=&output=embed', 450, 310, 'hoi-nghi-y-te-thong-minh-medtech-2026', 'Y Tế Thông Minh', 'https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 16, NULL, NULL);
INSERT INTO public.events VALUES (102, 'Hội Nghị EdTech Vietnam: Chuyển Đổi Số Giáo Dục & AI', 'Nâng cao chất lượng dạy và học qua nền tảng thích ứng theo năng lực cá nhân bằng AI, lớp học ảo Metaverse và tài nguyên giáo dục mở chuẩn quốc tế.', 49, 'Trường Đại Học Bách Khoa Hà Nội', '2026-10-28 08:30:00+00', '2026-10-29 17:00:00+00', 'PUBLISHED', '2026-09-25 02:21:54.69286+00', '2026-09-25 02:40:53.013618+00', '28/10/2026 08:30', '29/10/2026 17:00', 'Số 1 Đại Cồ Việt, Bách Khoa, Hai Bà Trưng, Hà Nội', 'https://maps.google.com/maps?q=Dai+Hoc+Bach+Khoa+Ha+Noi&t=&z=16&ie=UTF8&iwloc=&output=embed', 500, 350, 'edtech-vietnam-chuyen-doi-so-giao-duc-2026', 'Giáo Dục & EdTech', 'https://images.unsplash.com/photo-1524178232363-1fb2b075b655?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 17, NULL, NULL);
INSERT INTO public.events VALUES (103, 'Hội Thảo Smart City & Giao Thông Thông Minh 2026', 'Mô hình vận hành đô thị thông minh tích hợp cảm biến IoT điều tiết đèn giao thông theo mật độ thực tế, giám sát chất lượng không khí và hạ tầng số.', 50, 'Trung Tâm Hành Chính TP. Đà Nẵng', '2026-11-08 08:30:00+00', '2026-11-09 17:00:00+00', 'PUBLISHED', '2026-09-25 02:21:55.005918+00', '2026-09-25 02:40:53.334634+00', '08/11/2026 08:30', '09/11/2026 17:00', '24 Trần Phú, Thạch Thang, Hải Châu, Đà Nẵng', 'https://maps.google.com/maps?q=Trung+Tam+Hanh+Chinh+Da+Nang&t=&z=16&ie=UTF8&iwloc=&output=embed', 450, 320, 'smart-city-giao-thong-thong-minh-2026', 'Đô Thị Thông Minh', 'https://images.unsplash.com/photo-1519501025264-65ba15a82390?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 18, NULL, NULL);
INSERT INTO public.events VALUES (104, 'Vietnam AgriTech: Đột Phá Nông Nghiệp Công Nghệ Cao 2026', 'Giới thiệu máy bay không người lái phun tưới chính xác, hệ thống cảm biến độ ẩm đất IoT tự động, truy xuất nguồn gốc nông sản bằng Blockchain.', 51, 'Khách sạn Mường Thanh Luxury Cần Thơ', '2026-11-15 08:30:00+00', '2026-11-16 17:00:00+00', 'PUBLISHED', '2026-09-25 02:21:55.2165+00', '2026-09-25 02:40:53.642905+00', '15/11/2026 08:30', '16/11/2026 17:00', 'Khu E1, Cồn Cái Khế, Ninh Kiều, Cần Thơ', 'https://maps.google.com/maps?q=Muong+Thanh+Luxury+Can+Tho&t=&z=16&ie=UTF8&iwloc=&output=embed', 400, 260, 'vietnam-agritech-nong-nghiep-cong-nghe-cao-2026', 'Nông Nghiệp Công Nghệ Cao', 'https://images.unsplash.com/photo-1625246333195-78d9c38ad449?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 19, NULL, NULL);
INSERT INTO public.events VALUES (154, 'Vietnam E-Commerce Innovation & Live-Commerce Summit 2026', 'Bùng nổ xu hướng Live-Commerce, cá nhân hóa trải nghiệm mua sắm bằng Generative AI và thanh toán một chạm thế hệ mới trên các sàn thương mại điện tử.', 43, 'Trung Tâm Hội Nghị The Adora Center, TP. Hồ Chí Minh', '2026-12-05 08:30:00+00', '2026-12-06 18:00:00+00', 'PUBLISHED', '2026-09-29 00:11:39.28532+00', '2026-09-29 00:11:39.28532+00', '05/12/2026 08:30', '06/12/2026 18:00', '431 Hoàng Văn Thụ, Phường 4, Quận Tân Bình, TP. Hồ Chí Minh', 'https://maps.google.com/maps?q=The+Adora+Center+Hoang+Van+Thu&t=&z=16&ie=UTF8&iwloc=&output=embed', 900, 760, 'vietnam-ecommerce-live-commerce-summit-2026', 'Thương Mại Điện Tử', 'https://images.unsplash.com/photo-1556742049-0a67c5574f73?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 24, NULL, NULL);
INSERT INTO public.events VALUES (149, 'AI Summit Vietnam 2026: Kiến Tạo Tương Lai Số', 'Hội nghị thượng đỉnh quy tụ hơn 1,000 chuyên gia, CEO và nhà nghiên cứu AI hàng đầu thế giới thảo luận về Generative AI, Autonomous Agents, LLM trong doanh nghiệp và chiến lược chủ quyền dữ liệu quốc gia.', 36, 'Trung Tâm Hội Nghị Quốc Gia (NCC), Hà Nội', '2026-10-10 08:30:00+00', '2026-10-11 17:30:00+00', 'PUBLISHED', '2026-09-29 00:11:25.313431+00', '2026-09-29 00:11:25.313431+00', '10/10/2026 08:30', '11/10/2026 17:30', 'Đại lộ Thăng Long, Mễ Trì, Nam Từ Liêm, Hà Nội', 'https://maps.google.com/maps?q=National+Convention+Center+Hanoi&t=&z=16&ie=UTF8&iwloc=&output=embed', 1000, 780, 'ai-summit-vietnam-2026', 'Trí Tuệ Nhân Tạo', 'https://images.unsplash.com/photo-1540575467063-178a50c2df87?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, true, 1, NULL, NULL);
INSERT INTO public.events VALUES (150, 'Vietnam UI/UX Design & Product Innovation Forum 2026', 'Diễn đàn hàng đầu về thiết kế trải nghiệm người dùng, xây dựng Design System quy mô lớn, tương tác đa giác quan và ứng dụng AI hỗ trợ quy trình thiết kế giao diện sản phẩm số.', 54, 'Dreamplex Coworking Space, TP. Hồ Chí Minh', '2026-11-18 08:30:00+00', '2026-11-19 17:00:00+00', 'PUBLISHED', '2026-09-29 00:11:30.040793+00', '2026-09-29 00:11:30.040793+00', '18/11/2026 08:30', '19/11/2026 17:00', '195 Điện Biên Phủ, Phường 15, Bình Thạnh, TP. Hồ Chí Minh', 'https://maps.google.com/maps?q=Dreamplex+195+Dien+Bien+Phu&t=&z=16&ie=UTF8&iwloc=&output=embed', 450, 380, 'vietnam-uiux-design-product-innovation-2026', 'Thiết Kế Trải Nghiệm', 'https://images.unsplash.com/photo-1581291518857-4e27b48ff24e?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 6, NULL, NULL);
INSERT INTO public.events VALUES (151, 'Vietnam Smart Logistics & Supply Chain Automation Summit 2026', 'Ứng dụng robot AGV/AMR trong kho vận thông minh, tối ưu hóa tuyến đường vận tải bằng AI và giải pháp quản lý cảng biển thông minh thế hệ mới.', 52, 'Trung Tâm Hội Chợ Triển Lãm Quốc Tế Hải Phòng', '2026-11-28 08:30:00+00', '2026-11-29 17:00:00+00', 'PUBLISHED', '2026-09-29 00:11:37.680806+00', '2026-09-29 00:11:37.680806+00', '28/11/2026 08:30', '29/11/2026 17:00', 'Số 10 Phạm Văn Đồng, Dương Kinh, TP. Hải Phòng', 'https://maps.google.com/maps?q=Hai+Phong+International+Exhibition+Center&t=&z=16&ie=UTF8&iwloc=&output=embed', 550, 390, 'vietnam-smart-logistics-supply-chain-2026', 'Logistics & Supply Chain', 'https://images.unsplash.com/photo-1586528116311-ad8dd3c8310d?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 21, NULL, NULL);
INSERT INTO public.events VALUES (152, 'Vietnam Electric Vehicle (EV) & Smart Mobility Forum 2026', 'Diễn đàn hàng đầu về hạ tầng trạm sạc xe điện siêu nhanh, công nghệ pin thể rắn thế hệ mới và chính sách phát triển phương tiện giao thông xanh tại đô thị.', 48, 'Khách Sạn Pullman Danang Beach Resort', '2026-12-01 09:00:00+00', '2026-12-02 17:00:00+00', 'PUBLISHED', '2026-09-29 00:11:38.253977+00', '2026-09-29 00:11:38.253977+00', '01/12/2026 09:00', '02/12/2026 17:00', '101 Võ Nguyên Giáp, Phường Khuê Mỹ, Quận Ngũ Hành Sơn, Đà Nẵng', 'https://maps.google.com/maps?q=Pullman+Danang+Beach+Resort&t=&z=16&ie=UTF8&iwloc=&output=embed', 600, 430, 'vietnam-ev-smart-mobility-forum-2026', 'Xe Điện & Giao Thông Xanh', 'https://images.unsplash.com/photo-1593941707882-a5bba14938c7?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 22, NULL, NULL);
INSERT INTO public.events VALUES (88, 'Vietnam Cloud & DevOps Expo 2026', 'Sự kiện chuyên ngành về Điện toán đám mây thế hệ mới, Kubernetes, Microservices kiến trúc cao cấp và thực hành bảo mật DevSecOps trong môi trường đa đám mây (Multi-Cloud).', 37, 'GEM Center, TP. Hồ Chí Minh', '2026-11-12 09:00:00+00', '2026-11-13 17:00:00+00', 'PUBLISHED', '2026-09-25 02:21:51.463344+00', '2026-09-28 13:12:57.402592+00', '12/11/2026 09:00', '13/11/2026 17:00', 'Số 8 Nguyễn Bỉnh Khiêm, Phường Đa Kao, Quận 1, TP. Hồ Chí Minh', 'https://maps.google.com/maps?q=GEM+Center+Ho+Chi+Minh&t=&z=16&ie=UTF8&iwloc=&output=embed', 800, 560, 'vietnam-cloud-devops-expo-2026', 'Điện Toán Đám Mây', 'https://images.unsplash.com/photo-1517245386807-bb43f82c33c4?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 5, NULL, NULL);
INSERT INTO public.events VALUES (153, 'Hội Thảo Quốc Tế: Điện Toán Lượng Tử & Vật Liệu Tiên Tiến 2026', 'Tọa đàm chuyên sâu về thuật toán lượng tử, mã hóa hậu lượng tử (Post-Quantum Cryptography), siêu máy tính và vật liệu bán dẫn hai chiều tương lai.', 55, 'Viện Hàn Lâm Khoa Học và Công Nghệ Việt Nam (VAST)', '2026-12-03 08:30:00+00', '2026-12-04 17:00:00+00', 'PUBLISHED', '2026-09-29 00:11:38.73916+00', '2026-09-29 00:11:38.73916+00', '03/12/2026 08:30', '04/12/2026 17:00', '18 Hoàng Quốc Việt, Nghĩa Đô, Cầu Giấy, Hà Nội', 'https://maps.google.com/maps?q=Vietnam+Academy+of+Science+and+Technology+Hanoi&t=&z=16&ie=UTF8&iwloc=&output=embed', 400, 310, 'dien-toan-luong-tu-deeptech-2026', 'Điện Toán Lượng Tử', 'https://images.unsplash.com/photo-1635070041078-e363dbe005cb?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 23, NULL, NULL);
INSERT INTO public.events VALUES (155, 'Future of Work & HR Technology Conference Vietnam 2026', 'Ứng dụng AI trong tuyển dụng và đánh giá năng lực nhân tài, mô hình làm việc kết hợp linh hoạt (Hybrid Work) và nâng cao trải nghiệm số của nhân viên.', 43, 'Khách Sạn Pan Pacific Hanoi', '2026-12-08 09:00:00+00', '2026-12-09 17:00:00+00', 'PUBLISHED', '2026-09-29 00:11:39.870279+00', '2026-09-29 00:11:39.870279+00', '08/12/2026 09:00', '09/12/2026 17:00', 'Số 1 Đường Thanh Niên, Ba Đình, Hà Nội', 'https://maps.google.com/maps?q=Pan+Pacific+Hanoi&t=&z=16&ie=UTF8&iwloc=&output=embed', 450, 340, 'future-of-work-hr-tech-vietnam-2026', 'Công Nghệ Nhân Sự & HR Tech', 'https://images.unsplash.com/photo-1521737604893-d14cc237f11d?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 25, NULL, NULL);
INSERT INTO public.events VALUES (156, 'Vietnam PropTech & Smart Building Expo 2026', 'Triển lãm công nghệ quản lý tòa nhà thông minh BMS, mô hình thông tin công trình BIM, thực tế ảo tham quan dự án và số hóa tài sản bất động sản.', 50, 'Trung Tâm Hội Nghị Riverside Palace, TP. Hồ Chí Minh', '2026-12-10 08:30:00+00', '2026-12-11 17:00:00+00', 'PUBLISHED', '2026-09-29 00:11:40.449265+00', '2026-09-29 00:11:40.449265+00', '10/12/2026 08:30', '11/12/2026 17:00', '360D Bến Vân Đồn, Phường 1, Quận 4, TP. Hồ Chí Minh', 'https://maps.google.com/maps?q=Riverside+Palace+Ben+Van+Don&t=&z=16&ie=UTF8&iwloc=&output=embed', 500, 370, 'vietnam-proptech-smart-building-expo-2026', 'Công Nghệ Bất Động Sản', 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 26, NULL, NULL);
INSERT INTO public.events VALUES (157, 'Vietnam Open Source & Linux Developers Summit 2026', 'Đại hội cộng đồng lập trình viên mã nguồn mở, chia sẻ kinh nghiệm đóng góp dự án GitHub/Linux Kernel, bảo mật phần mềm Supply Chain và giấy phép mã nguồn mở.', 42, 'Trường Đại học Khoa học Tự nhiên - ĐHQG Hà Nội', '2026-12-12 08:30:00+00', '2026-12-13 17:30:00+00', 'PUBLISHED', '2026-09-29 00:11:40.785897+00', '2026-09-29 00:11:40.785897+00', '12/12/2026 08:30', '13/12/2026 17:30', '334 Nguyễn Trãi, Thanh Xuân Trung, Thanh Xuân, Hà Nội', 'https://maps.google.com/maps?q=Dai+Hoc+Khoa+Hoc+Tu+Nhien+Ha+Noi&t=&z=16&ie=UTF8&iwloc=&output=embed', 650, 520, 'vietnam-open-source-summit-2026', 'Mã Nguồn Mở & Linux', 'https://images.unsplash.com/photo-1515879218367-8466d910aaa4?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 27, NULL, NULL);
INSERT INTO public.events VALUES (158, 'SpaceTech & Satellite Communications Forum Vietnam 2026', 'Khám phá công nghệ chế tạo vệ tinh nhỏ quan sát trái đất, viễn thám phục vụ cảnh báo thiên tai, nông nghiệp thông minh và internet vệ tinh quỹ đạo thấp LEO.', 55, 'Trung Tâm Vũ Trụ Việt Nam (VNSC), Khu CNC Hòa Lạc', '2026-12-14 09:00:00+00', '2026-12-15 16:30:00+00', 'PUBLISHED', '2026-09-29 00:11:41.189296+00', '2026-09-29 00:11:41.189296+00', '14/12/2026 09:00', '15/12/2026 16:30', 'Km 29 Đại lộ Thăng Long, Thạch Thất, Hà Nội', 'https://maps.google.com/maps?q=Vietnam+National+Space+Center+Hoa+Lac&t=&z=16&ie=UTF8&iwloc=&output=embed', 350, 260, 'spacetech-satellite-communications-vietnam-2026', 'Công Nghệ Vũ Trụ', 'https://images.unsplash.com/photo-1451187580459-43490279c0fa?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 28, NULL, NULL);
INSERT INTO public.events VALUES (159, 'AI Marketing & Creative Content Creation Forum 2026', 'Chiến lược ứng dụng AI tạo sinh trong sản xuất video, tối ưu chiến dịch quảng cáo đa kênh tự động và cá nhân hóa thông điệp tiếp thị thương hiệu.', 36, 'Khách Sạn Caravelle Saigon', '2026-12-16 08:30:00+00', '2026-12-17 17:00:00+00', 'PUBLISHED', '2026-09-29 00:11:41.705873+00', '2026-09-29 00:11:41.705873+00', '16/12/2026 08:30', '17/12/2026 17:00', '19-23 Lam Sơn Square, Bến Nghé, Quận 1, TP. Hồ Chí Minh', 'https://maps.google.com/maps?q=Caravelle+Saigon&t=&z=16&ie=UTF8&iwloc=&output=embed', 500, 440, 'ai-marketing-content-creation-forum-2026', 'AI Marketing & Sáng Tạo', 'https://images.unsplash.com/photo-1542744094-3a31727221eb?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 29, NULL, NULL);
INSERT INTO public.events VALUES (160, 'Vietnam BioTechnology & Genome Engineering Conference 2026', 'Diễn đàn chuyên môn về công nghệ chỉnh sửa gen CRISPR, giải trình tự gen thế hệ mới phục vụ y học chính xác và bảo tồn đa dạng sinh học.', 47, 'Viện Hàn Lâm Khoa Học và Công Nghệ Việt Nam, Hà Nội', '2026-12-18 08:30:00+00', '2026-12-19 17:00:00+00', 'PUBLISHED', '2026-09-29 00:11:42.326585+00', '2026-09-29 00:11:42.326585+00', '18/12/2026 08:30', '19/12/2026 17:00', '18 Hoàng Quốc Việt, Cầu Giấy, Hà Nội', 'https://maps.google.com/maps?q=Institute+of+Biotechnology+VAST+Hanoi&t=&z=16&ie=UTF8&iwloc=&output=embed', 400, 290, 'vietnam-biotech-genome-engineering-2026', 'Công Nghệ Sinh Học', 'https://images.unsplash.com/photo-1532187863486-abf9dbad1b69?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 30, NULL, NULL);
INSERT INTO public.events VALUES (161, 'Vietnam 5G/6G Infrastructure & Edge Cloud Summit 2026', 'Đẩy mạnh thương mại hóa mạng 5G Advanced độc lập (SA), nghiên cứu tiền trạm 6G và triển khai tính toán biên (Multi-Access Edge Computing) độ trễ siêu thấp.', 37, 'Tòa Nhà Viettel Telecom Cầu Giấy, Hà Nội', '2026-12-20 09:00:00+00', '2026-12-21 17:00:00+00', 'PUBLISHED', '2026-09-29 00:11:42.831631+00', '2026-09-29 00:11:42.831631+00', '20/12/2026 09:00', '21/12/2026 17:00', 'Số 1 Trần Hữu Dực, Mỹ Đình, Nam Từ Liêm, Hà Nội', 'https://maps.google.com/maps?q=Viettel+Headquarters+Hanoi&t=&z=16&ie=UTF8&iwloc=&output=embed', 700, 510, 'vietnam-5g-6g-edge-cloud-summit-2026', 'Hạ Tầng Viễn Thông 5G/6G', 'https://images.unsplash.com/photo-1544197150-b99a580bb7a8?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 31, NULL, NULL);
INSERT INTO public.events VALUES (162, 'Spatial Computing & AR/VR Developers Expo Vietnam 2026', 'Trải nghiệm kính thực tế ảo tăng cường thế hệ mới, phát triển ứng dụng Spatial Computing trên VisionOS, Unity, WebXR phục vụ giáo dục và đào tạo kỹ thuật.', 42, 'Trung Tâm Hội Chợ & Triển Lãm Sài Gòn (SECC), TP. Hồ Chí Minh', '2026-12-22 09:00:00+00', '2026-12-23 18:00:00+00', 'PUBLISHED', '2026-09-29 00:11:43.52804+00', '2026-09-29 00:11:43.52804+00', '22/12/2026 09:00', '23/12/2026 18:00', '799 Nguyễn Văn Linh, Tân Phú, Quận 7, TP. Hồ Chí Minh', 'https://maps.google.com/maps?q=SECC+Quan+7+Ho+Chi+Minh&t=&z=16&ie=UTF8&iwloc=&output=embed', 800, 620, 'spatial-computing-ar-vr-expo-vietnam-2026', 'Điện Toán Không Gian & AR/VR', 'https://images.unsplash.com/photo-1592478411213-6153e4ebc07d?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 32, NULL, NULL);
INSERT INTO public.events VALUES (163, 'Vietnam InsurTech & Digital Underwriting Summit 2026', 'Tự động hóa quy trình thẩm định bảo hiểm, bồi thường trực tuyến siêu tốc bằng AI và dữ liệu viễn thông Telematics bảo hiểm phương tiện cá nhân hóa.', 41, 'Khách Sạn Meliá Hanoi', '2026-12-24 08:30:00+00', '2026-12-25 16:30:00+00', 'PUBLISHED', '2026-09-29 00:11:44.126494+00', '2026-09-29 00:11:44.126494+00', '24/12/2026 08:30', '25/12/2026 16:30', '44B Lý Thường Kiệt, Trần Hưng Đạo, Hoàn Kiếm, Hà Nội', 'https://maps.google.com/maps?q=Melia+Hanoi+Hotel&t=&z=16&ie=UTF8&iwloc=&output=embed', 450, 315, 'vietnam-insurtech-digital-underwriting-2026', 'Bảo Hiểm Công Nghệ', 'https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 33, NULL, NULL);
INSERT INTO public.events VALUES (164, 'Vietnam CleanTech & Circular Economy Forum 2026', 'Giải pháp tái chế rác thải điện tử công nghệ cao, xử lý nước tuần hoàn không xả thải và vật liệu sinh học tự phân hủy thay thế đồ nhựa dùng một lần.', 48, 'Khách Sạn The Imperial Hotel Vũng Tàu', '2026-12-26 09:00:00+00', '2026-12-27 17:00:00+00', 'PUBLISHED', '2026-09-29 00:11:44.648773+00', '2026-09-29 00:11:44.648773+00', '26/12/2026 09:00', '27/12/2026 17:00', '159 Thùy Vân, Phường Thắng Tam, TP. Vũng Tàu, Bà Rịa - Vũng Tàu', 'https://maps.google.com/maps?q=The+Imperial+Hotel+Vung+Tau&t=&z=16&ie=UTF8&iwloc=&output=embed', 400, 280, 'vietnam-cleantech-circular-economy-2026', 'Công Nghệ Môi Trường', 'https://images.unsplash.com/photo-1473341304170-971dccb5ac1e?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 34, NULL, NULL);
INSERT INTO public.events VALUES (165, 'Vietnam National Cyber Defense & Red Team Drill 2026', 'Diễn tập thực chiến phòng thủ an ninh mạng quy mô quốc gia giữa các đội Red Team (Tấn công) và Blue Team (Phòng thủ) bảo vệ hạ tầng trọng yếu.', 40, 'Trung Tâm Giám Sát An Toàn Không Gian Mạng Quốc Gia (NCSC)', '2026-12-28 08:00:00+00', '2026-12-28 18:00:00+00', 'PUBLISHED', '2026-09-29 00:11:45.247233+00', '2026-09-29 00:11:45.247233+00', '28/12/2026 08:00', '28/12/2026 18:00', 'Tòa nhà Cục An Toàn Thông Tin, Yên Hòa, Cầu Giấy, Hà Nội', 'https://maps.google.com/maps?q=National+Cyber+Security+Center+Hanoi&t=&z=16&ie=UTF8&iwloc=&output=embed', 350, 310, 'vietnam-cyber-defense-red-team-drill-2026', 'Diễn Tập An Ninh Mạng Quốc Gia', 'https://images.unsplash.com/photo-1563986768609-322da13575f3?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 35, NULL, NULL);
INSERT INTO public.events VALUES (166, 'Vietnam Web3 Gaming & Virtual Economies Summit 2026', 'Mô hình kinh tế số cân bằng trong game thế hệ mới, sở hữu tài sản kỹ thuật số phi tập trung và cơ chế chống lạm phát token trong hệ sinh thái gaming.', 38, 'Khách Sạn Novotel Danang Premier Han River', '2026-12-29 09:00:00+00', '2026-12-30 17:30:00+00', 'PUBLISHED', '2026-09-29 00:11:45.804966+00', '2026-09-29 00:11:45.804966+00', '29/12/2026 09:00', '30/12/2026 17:30', '36 Bạch Đằng, Thạch Thang, Hải Châu, Đà Nẵng', 'https://maps.google.com/maps?q=Novotel+Danang+Premier+Han+River&t=&z=16&ie=UTF8&iwloc=&output=embed', 500, 395, 'vietnam-web3-gaming-virtual-economies-2026', 'Web3 Gaming & Kinh Tế Số', 'https://images.unsplash.com/photo-1538481199705-c710c4e965fc?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 36, NULL, NULL);
INSERT INTO public.events VALUES (167, 'Vietnam CIO & CTO Leadership Summit: Horizon 2027', 'Diễn đàn kín dành cho 300 Giám đốc Công nghệ (CTO) và Giám đốc CNTT (CIO) hàng đầu hoạch định chiến lược đầu tư công nghệ và định hình chuyển đổi số giai đoạn 2027.', 43, 'Khách Sạn Park Hyatt Saigon, TP. Hồ Chí Minh', '2026-12-30 14:00:00+00', '2026-12-31 18:00:00+00', 'PUBLISHED', '2026-09-29 00:11:46.269451+00', '2026-09-29 00:11:46.269451+00', '30/12/2026 14:00', '31/12/2026 18:00', 'Số 2 Công Trường Lam Sơn, Bến Nghé, Quận 1, TP. Hồ Chí Minh', 'https://maps.google.com/maps?q=Park+Hyatt+Saigon&t=&z=16&ie=UTF8&iwloc=&output=embed', 300, 260, 'vietnam-cio-cto-leadership-summit-2026', 'Lãnh Đạo Công Nghệ Cấp Cao', 'https://images.unsplash.com/photo-1515187029135-18ee286d815b?ixlib=rb-4.0.3&auto=format&fit=crop&w=1200&q=80', true, false, 37, NULL, NULL);
